nginx_config:
daemon off;
master_process on;
worker_processes 2;
pid /tmp/aegisx-bench-ne8ys61q/nginx.pid;
error_log /tmp/aegisx-bench-ne8ys61q/nginx-error.log crit;
events { worker_connections 16384; multi_accept on; }
http {
    access_log off;
    client_body_temp_path /tmp/aegisx-bench-ne8ys61q/body;
    proxy_temp_path /tmp/aegisx-bench-ne8ys61q/proxy;
    keepalive_timeout 60s;
    keepalive_requests 100000;

    upstream origin { server 10.42.1.170:3900; keepalive 256; }
    server {
        listen 10.42.1.79:2477 ssl  reuseport;
        ssl_certificate /tmp/aegisx-bench-ne8ys61q/cert.pem;
        ssl_certificate_key /tmp/aegisx-bench-ne8ys61q/key.pem;
        ssl_protocols TLSv1.2 TLSv1.3;
        ssl_session_cache shared:SSL:10m;
        ssl_session_tickets on;
        http2_max_concurrent_streams 256;
        location / {
            proxy_http_version 1.1;
            proxy_set_header Connection "";
            proxy_set_header Host 10.42.1.170:3900;
            proxy_request_buffering off;
            proxy_buffering off;
            proxy_pass http://origin;
        }
    }
}
